// toBinary_HIRA.cpp
// Converts the text HiRA strip table into the binary .dat read by HiRAGeometry (STRIP_TABLE in HiRAConfig.dat)
//
// Usage: bin/toBinary_HIRA input/HIRA/geometry/HiRA_channel_theta_phi.txt input/HIRA/HiRA_channel_theta_phi.dat
// Built by CMake (bin/toBinary_HIRA).
//
// Text input (generated by build_hira_geometry.py), one strip per line, whitespace- or
// comma-separated, '#' = comment:
//   motherboard chip detCode strip telescope face csiA csiB
//   theta thetaMin thetaMax dtheta phi phiMin phiMax dphi
// face: 0 = front (EF), 1 = back (EB). csiA/csiB: the two CsI behind the strip.
//
// Binary record (108 bytes, must match HiRAGeometry.h):
//   int32 motherboard, chip; char detCode[16]; int32 strip, telescope, face, csiA, csiB;
//   double theta, thetaMin, thetaMax, dtheta, phi, phiMin, phiMax, dphi
#include <algorithm>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <sstream>
#include <string>

int main(int argc, char** argv) {
    const char* in  = argc > 1 ? argv[1] : "HiRA_channel_theta_phi.txt";
    const char* out = argc > 2 ? argv[2] : "HiRA_channel_theta_phi.dat";
    const int kCodeLen = 16;    // must match HiRAGeometry::LoadStrips

    std::ifstream fin(in);
    std::ofstream fout(out, std::ios::binary);
    if (!fin || !fout) { std::fprintf(stderr, "Cannot open input/output file\n"); return 1; }

    std::string line, code;
    int n = 0, lineNo = 0;

    while (std::getline(fin, line)) {
        lineNo++;
        std::replace(line.begin(), line.end(), ',', ' ');
        size_t first = line.find_first_not_of(" \t\r");
        if (first == std::string::npos || line[first] == '#') continue;   // skip header/blank

        int mb, chip, strip, tele, face, csiA, csiB;
        double ang[8];      // theta, thetaMin, thetaMax, dtheta, phi, phiMin, phiMax, dphi
        std::istringstream ss(line);
        if (!(ss >> mb >> chip >> code >> strip >> tele >> face >> csiA >> csiB
                 >> ang[0] >> ang[1] >> ang[2] >> ang[3] >> ang[4] >> ang[5] >> ang[6] >> ang[7])) {
            std::fprintf(stderr, "line %d: could not parse (old 8-column format?), skipped\n", lineNo);
            continue;
        }
        if ((int)code.size() >= kCodeLen) {
            std::fprintf(stderr, "line %d: detector code '%s' longer than %d chars, skipped\n",
                         lineNo, code.c_str(), kCodeLen - 1);
            continue;
        }

        int32_t ints1[2] = {mb, chip};
        int32_t ints2[5] = {strip, tele, face, csiA, csiB};
        char codeBuf[kCodeLen];
        std::memset(codeBuf, 0, kCodeLen);
        std::memcpy(codeBuf, code.c_str(), code.size());

        fout.write(reinterpret_cast<const char*>(ints1), sizeof ints1);
        fout.write(codeBuf, kCodeLen);
        fout.write(reinterpret_cast<const char*>(ints2), sizeof ints2);
        fout.write(reinterpret_cast<const char*>(ang),   sizeof ang);
        ++n;
    }
    std::printf("Wrote %d strips to %s\n", n, out);
    return 0;
}
